import asyncio

class BulkheadPool:
    def __init__(self, name: str, max_concurrent: int, timeout_s: float):
        self.name = name
        self.sem = asyncio.Semaphore(max_concurrent)
        self.timeout_s = timeout_s

    async def run(self, coro_fn, fallback=None):
        if self.sem.locked():  # Fail fast when bulkhead is saturated
            if fallback is not None:
                return fallback()
            raise RuntimeError(f"Bulkhead {self.name} saturated")
        async with self.sem:
            async with asyncio.timeout(self.timeout_s):
                return await coro_fn()
